    ],
    "lacunas": [],
    "motivo": "Término de referência declarado como D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"},
      {"fonte_id": "f_a781", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["A nova duração de usinar corpo pode ser qualquer inteiro não negativo; sua magnitude não foi fixada."],
    "motivo": "A duração desconhecida pode deixar o marco em D12 ou atrasá-lo; não há suporte para um término exato.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["A magnitude da duração redefinida é desconhecida; o término pode permanecer em D12 ou ocorrer depois."],
    "motivo": "O aviso não permite determinar se a variação é zero ou atraso, nem sua magnitude.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": [],
    "motivo": "Custo de referência declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_b915", "localizador": "L01"}
    ],
    "lacunas": ["A duração redefinida pode alterar a extensão do apoio; não se conhece a magnitude de eventual cobrança adicional por dias extras."],
    "motivo": "Há acréscimo direto de R$ 25,00, mas o custo total também pode aumentar com a extensão do apoio; o valor exato não é determinável.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_b915", "localizador": "L01"}
    ],
    "lacunas": ["Magnitude total desconhecida: o acréscimo direto é de 2500 centavos, e eventual extensão além de D12 pode elevar o custo do apoio."],
    "motivo": "O aviso acrescenta R$ 25,00 sem retirar custos existentes; qualquer extensão adicional do apoio aumenta ainda mais o custo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A duração de usinar corpo não foi fixada e pode manter o marco em D12 ou atrasá-lo. O custo aumenta ao menos 2500 centavos pela cobrança direta, mas eventual extensão do apoio impede determinar o aumento total."
}

